parameters.command:
set -e
rm -rf /tmp/train "$HOME/.thunderbird/mail.default-release"
profile="$HOME/.thunderbird/mail.default-release"
mkdir -p /tmp/train "$profile/Mail/Local Folders" "$profile/Mail/localhost"
cat > "$HOME/.thunderbird/profiles.ini" <<'EOF'
[Profile0]
Name=local
IsRelative=1
Path=mail.default-release
Default=1

[General]
StartWithLastProfile=1
Version=2
EOF
cat > "$profile/prefs.js" <<'EOF'
user_pref("mail.account.account1.identities", "id1");
user_pref("mail.account.account1.server", "server2");
user_pref("mail.accountmanager.accounts", "account1");
user_pref("mail.accountmanager.defaultaccount", "account1");
user_pref("mail.accountmanager.localfoldersserver", "server1");
user_pref("mail.identity.id1.email", "agent@example.test");
user_pref("mail.identity.id1.fullName", "Local Agent");
user_pref("mail.identity.id1.draft_folder", "mailbox://nobody@Local%20Folders/Drafts");
user_pref("mail.identity.id1.fcc_folder", "mailbox://nobody@Local%20Folders/Sent");
user_pref("mail.identity.id1.smtpServer", "smtp1");
user_pref("mail.server.server1.directory", "[ProfD]Mail/Local Folders");
user_pref("mail.server.server1.directory-rel", "[ProfD]Mail/Local Folders");
user_pref("mail.server.server1.hostname", "Local Folders");
user_pref("mail.server.server1.name", "Local Folders");
user_pref("mail.server.server1.type", "none");
user_pref("mail.server.server1.userName", "nobody");
user_pref("mail.server.server2.check_new_mail", false);
user_pref("mail.server.server2.directory", "[ProfD]Mail/localhost");
user_pref("mail.server.server2.directory-rel", "[ProfD]Mail/localhost");
user_pref("mail.server.server2.download_on_biff", false);
user_pref("mail.server.server2.hostname", "localhost");
user_pref("mail.server.server2.login_at_startup", false);
user_pref("mail.server.server2.name", "Local Agent");
user_pref("mail.server.server2.port", 110);
user_pref("mail.server.server2.socketType", 0);
user_pref("mail.server.server2.type", "pop3");
user_pref("mail.server.server2.userName", "agent");
user_pref("mail.smtp.defaultserver", "smtp1");
user_pref("mail.smtpserver.smtp1.hostname", "localhost");
user_pref("mail.smtpserver.smtp1.port", 25);
user_pref("mail.smtpserver.smtp1.try_ssl", 0);
user_pref("mail.smtpserver.smtp1.username", "agent");
user_pref("mail.smtpservers", "smtp1");
user_pref("mail.provider.suppress_dialog_on_startup", true);
user_pref("mail.shell.checkDefaultClient", false);
user_pref("mailnews.start_page.enabled", false);
EOF
: > "$profile/Mail/Local Folders/Inbox"
: > "$profile/Mail/Local Folders/Drafts"
: > "$profile/Mail/Local Folders/Sent"

result.command:
PDF='/tmp/train/training_deck.pdf'
[ -s "$PDF" ] && [ "$(head -c 5 "$PDF" 2>/dev/null)" = '%PDF-' ] || { echo invalid; exit 0; }
command -v pdftotext >/dev/null 2>&1 || { echo missing; exit 0; }
TMP=$(mktemp)
pdftotext /tmp/train/training_deck.pdf "$TMP" 2>/dev/null || { rm -f "$TMP"; echo invalid; exit 0; }
cat "$TMP"
rm -f "$TMP"
